/**
 * Handle cancel-request clicks on the "My requests" datatable.
 *
 * @module local_sentientia_request/my_requests
 *
 * Build note (2026-05-22, Goal A audit Bug #6 fix): this file is hand-
 * rolled from amd/src/my_requests.js to AMD format because no grunt
 * build was checked in. The ES6 src imports `core/ajax` + `core/notification`;
 * the AMD equivalent passes those into `define()`. If you regenerate
 * this via `npx grunt amd` later, the output will be similar but
 * minified (current version is readable for debug-mode tooling).
 */
define(["core/ajax", "core/notification"], function (Ajax, Notification) {
    "use strict";

    var init = function () {
        document.addEventListener("click", function (e) {
            var btn = e.target.closest('[data-action="cancel-request"]');
            if (!btn) return;
            e.preventDefault();
            var requestid = parseInt(btn.dataset.requestid, 10);
            if (!requestid) return;
            if (!confirm("Cancel this request?")) return;

            Ajax.call([
                {
                    methodname: "local_sentientia_request_cancel",
                    args: { requestid: requestid }
                }
            ])[0]
                .then(function () {
                    window.location.reload();
                })
                .catch(Notification.exception);
        });
    };

    return { init: init };
});
